package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OrderColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.claim.Tags;
import org.hibernate.annotations.OptimisticLock;

/** A person on a sheet: a name and a grade (one of the sheet's), dated: each grade applies from its from-date. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The person's place in the sheet's list, smallest first; a new person goes to the end. */
    @Column(name = "position", nullable = false)
    private long position;

    /** The grades the person was given, each from its from-date; the first has none. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<GradeFrom> grades = new ArrayList<>();

    /** The day the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The person's past retirements: each from the day they were retired from to the day they were
     *  unretired. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
    private List<Retirement> retirements = new ArrayList<>();

    /** The person's holds: while one is in force on the sheet's today they get no cut of the pools,
     *  their share spread over the others. Their claims still count in every total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** The person's snapshots, oldest first; writing one does not raise the version. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_snapshot", joinColumns = @JoinColumn(name = "person_id"))
    @OrderColumn(name = "position")
    @OptimisticLock(excluded = true)
    private List<Snapshot> snapshots = new ArrayList<>();

    /** The person's own terms in days; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's own terms recorded from a from-date, each until a later one takes over. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_terms", joinColumns = @JoinColumn(name = "person_id"))
    private List<TermsFrom> datedTerms = new ArrayList<>();

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The person's tags, sorted and comma separated (see {@link Tags}); null when they have none. */
    @Column(name = "tags")
    private String tags;

    /** The person's aliases, each trimmed; unique on the sheet among names and aliases as names are
     *  compared. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias")
    private Set<String> aliases = new HashSet<>();

    /** The sheet the person was transferred from; null when they were not transferred. */
    @Column(name = "origin")
    private String origin;

    /** The sheet's today on which the person arrived on it by a transfer; null when they did not. */
    @Column(name = "arrived_on")
    private LocalDate arrivedOn;

    /** The reason the person is flagged; null when they never were. */
    @Column(name = "flag_reason")
    private String flagReason;

    /** The last day (included) the person's flag is in force; null when they were never flagged. */
    @Column(name = "flag_until")
    private LocalDate flagUntil;

    /** The user who may approve or reject the person's pending claims as a steward may; null when
     *  they have none. */
    @Column(name = "approver")
    private String approver;

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    /** A detached person with the id given and no grade yet, for a revision to fill in (see
     *  {@link PersonRevision#toPerson}). */
    Person(String sheetId, Long id, String name) {
        this.sheetId = sheetId;
        this.id = id;
        this.name = name;
    }

    public Person(String sheetId, String name, String grade, long position) {
        this.sheetId = sheetId;
        this.name = name;
        this.position = position;
        this.grades.add(new GradeFrom(null, grade));
    }

    /** A copy of the person for another sheet (they were transferred there): their name, every
     *  grade they were given (and its from-date), terms, contact, tags and aliases; no holds. They take
     *  the place given in that sheet's list. */
    public Person transferredTo(String toSheetId, long toPosition) {
        return transferredTo(toSheetId, toPosition, null);
    }

    /** As {@link #transferredTo(String, long)}, arriving there on the day given (that sheet's today). */
    public Person transferredTo(String toSheetId, long toPosition, LocalDate arrivedOn) {
        Person copy = new Person(toSheetId, (Long) null, name);
        copy.position = toPosition;
        grades.forEach(g -> copy.grades.add(new GradeFrom(g.getFromDate(), g.getGrade())));
        copy.terms = terms;
        datedTerms.forEach(t -> copy.datedTerms.add(new TermsFrom(t.getFromDate(), t.getTerms())));
        copy.contact = contact;
        copy.tags = tags;
        copy.aliases.addAll(aliases);
        copy.origin = sheetId;
        copy.arrivedOn = arrivedOn;
        return copy;
    }

    /** A copy of the person for a clone of their sheet: their name, place in the list, every grade
     *  they were given (and its from-date), terms, contact, aliases, holds, flag, retirement and past
     *  retirements, approver, and the sheet they were transferred from. */
    public Person clonedTo(String toSheetId) {
        Person copy = transferredTo(toSheetId, position);
        copy.origin = origin;
        copy.retiredFrom = retiredFrom;
        retirements.forEach(r -> copy.retirements.add(new Retirement(r.getFromDate(), r.getToDate())));
        holds.forEach(h -> copy.holds.add(new Hold(h.getFromDate(), h.getToDate())));
        copy.flagReason = flagReason;
        copy.flagUntil = flagUntil;
        copy.approver = approver;
        return copy;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public long getPosition() {
        return position;
    }

    /** The grades the person was given, earliest from-date first, the one with none first of all. */
    public List<GradeFrom> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(GradeFrom::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on a day: the one with the latest from-date on or before it, or else the
     *  one with no from-date. */
    public String gradeOn(LocalDate day) {
        String on = null;
        for (GradeFrom g : getGrades()) {
            if (g.getFromDate() == null || !g.getFromDate().isAfter(day)) {
                on = g.getGrade();
            }
        }
        return on;
    }

    /** Record a grade from a day (null: the beginning of time), replacing the one recorded for that
     *  day, keeping the others. */
    public void setGradeFrom(String grade, LocalDate from) {
        grades.removeIf(g -> Objects.equals(from, g.getFromDate()));
        grades.add(new GradeFrom(from, grade));
    }

    /** Make every grade recorded for the person on one grade the other, keeping its from-date. */
    public void regrade(String from, String into) {
        grades.replaceAll(g -> from.equals(g.getGrade()) ? new GradeFrom(g.getFromDate(), into) : g);
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Whether the person is retired: they are as soon as a retirement day is set, whatever the day. */
    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether the person is retired on a day: their retirement day is set and the day is on or after it.
     *  From then their open claims unbound by a statement count in no live total. */
    public boolean isRetiredOn(LocalDate day) {
        return retiredFrom != null && !day.isBefore(retiredFrom);
    }

    /** The person's past retirements, earliest from-date first. */
    public List<Retirement> getRetirements() {
        return retirements.stream().sorted(Comparator.comparing(Retirement::getFromDate)
                .thenComparing(Retirement::getToDate)).toList();
    }

    /** Add a past retirement, keeping the others. */
    public void addRetirement(LocalDate from, LocalDate to) {
        retirements.add(new Retirement(from, to));
    }

    /** Unretire the person on a day: their retirement is kept as a past one, to that day. */
    public void unretire(LocalDate on) {
        retirements.add(new Retirement(retiredFrom, on));
        retiredFrom = null;
    }

    /** Whether a day falls after the from-date and before the to-date of a past retirement. */
    public boolean isWithinPastRetirement(LocalDate day) {
        return retirements.stream().anyMatch(r -> r.within(day));
    }

    /** The person's snapshots, oldest first. */
    public List<Snapshot> getSnapshots() {
        return List.copyOf(snapshots);
    }

    /** Add a snapshot after the others. */
    public void addSnapshot(LocalDate day, String dueTotal) {
        snapshots.add(new Snapshot(day, dueTotal));
    }

    /** The person's holds, earliest from-date first, those with none first of all. */
    public List<Hold> getHolds() {
        return holds.stream()
                .sorted(Comparator.comparing(Hold::getFromDate, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** Whether the person has any hold, whatever its days. */
    public boolean isHeld() {
        return !holds.isEmpty();
    }

    /** Whether one of the person's holds covers a day. */
    public boolean isHeldOn(LocalDate day) {
        return holds.stream().anyMatch(h -> h.covers(day));
    }

    /** Add a hold, keeping the others. */
    public void addHold(LocalDate from, LocalDate to) {
        holds.add(new Hold(from, to));
    }

    /** Flag the person with a reason until a day (included), replacing any flag they had. */
    public void flag(String reason, LocalDate until) {
        this.flagReason = reason;
        this.flagUntil = until;
    }

    /** The reason the person's flag gives while it is in force on a day; null when it is not. */
    public String flagOn(LocalDate day) {
        return flagUntil != null && !day.isAfter(flagUntil) ? flagReason : null;
    }

    /** Whether the person's flag is in force on a day: on or before its until-date. */
    public boolean isFlaggedOn(LocalDate day) {
        return flagOn(day) != null;
    }

    /** The person's own undated terms in days (from the beginning of time, until their earliest
     *  dated terms), ahead of their grade's and the sheet's; null when none. */
    public Integer getTerms() {
        return terms;
    }

    public void setTerms(Integer terms) {
        this.terms = terms;
    }

    /** The person's own terms recorded from a from-date, earliest first. */
    public List<TermsFrom> getDatedTerms() {
        return datedTerms.stream().sorted(Comparator.comparing(TermsFrom::getFromDate)).toList();
    }

    /** The person's own terms in force on a day: those with the latest from-date on or before it,
     *  or else their undated terms; null when none are in force (their grade's or the sheet's apply). */
    public Integer termsOn(LocalDate day) {
        Integer on = terms;
        for (TermsFrom t : getDatedTerms()) {
            if (!t.getFromDate().isAfter(day)) {
                on = t.getTerms();
            }
        }
        return on;
    }

    /** Record the person's own terms (null: none) from a day, replacing those recorded for that day
     *  and keeping the others; with no day, set their undated terms. */
    public void setTermsFrom(Integer terms, LocalDate from) {
        if (from == null) {
            this.terms = terms;
            return;
        }
        datedTerms.removeIf(t -> from.equals(t.getFromDate()));
        datedTerms.add(new TermsFrom(from, terms));
    }

    /** The sheet the person was transferred from; null when they were not transferred. */
    public String getOrigin() {
        return origin;
    }

    /** The sheet's today on which the person arrived on it by a transfer; null when they did not. */
    public LocalDate getArrivedOn() {
        return arrivedOn;
    }

    /** The user who may approve or reject the person's pending claims; null when they have none. */
    public String getApprover() {
        return approver;
    }

    public void setApprover(String approver) {
        this.approver = approver;
    }

    /** Whether the user is the person's approver. */
    public boolean isApprover(String user) {
        return approver != null && approver.equals(user);
    }

    /** The person's contact, held by no one else on the sheet; null when they have none. */
    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    /** The person's tags as stored (see {@link Tags}); null when they have none. */
    public String getTags() {
        return tags;
    }

    public void setTags(String tags) {
        this.tags = tags;
    }

    /** The person's aliases, sorted as names are compared: without regard to case. */
    public List<String> getAliases() {
        return aliases.stream()
                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(Comparator.naturalOrder()))
                .toList();
    }

    /** Add an alias, keeping the others. */
    public void addAlias(String alias) {
        aliases.add(alias);
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import java.util.Collection;
import java.util.List;
import java.util.Optional;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** The people on a sheet in list order: by position, then in the order they were added. */
    List<Person> findBySheetIdOrderByPositionAscIdAsc(String sheetId);

    /** The position after the last on the sheet's list: where a new person goes. */
    @Query("select coalesce(max(p.position), 0) + 1 from Person p where p.sheetId = :sheetId")
    long nextPosition(String sheetId);

    /** Put a person at a position in the list. Moving a person is no edit of them: their version
     *  stays as it is. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query("update Person p set p.position = :position where p.id = :id")
    void placeAt(Long id, long position);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** A person on a sheet, locked for the rest of the transaction so two statements of them are
     *  taken one after the other. Locking does not raise their version. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Person p where p.id = :id and p.sheetId = :sheetId")
    Optional<Person> lockByIdAndSheetId(Long id, String sheetId);

    /** Whether the name is in use on the sheet, compared without regard to case. */
    boolean existsBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** The person on the sheet with the name, compared without regard to case. */
    Optional<Person> findBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** Whether the contact is held on the sheet. */
    boolean existsBySheetIdAndContact(String sheetId, String contact);

    /** Whether the contact is held on the sheet by anyone but this person. */
    boolean existsBySheetIdAndContactAndIdNot(String sheetId, String contact, Long id);

    /** Whether the name is in use on the sheet by anyone but this person. */
    boolean existsBySheetIdAndNameIgnoreCaseAndIdNot(String sheetId, String name, Long id);

    /** Whether the text is an alias of anyone on the sheet, compared as names are. */
    @Query("select count(p) > 0 from Person p join p.aliases a where p.sheetId = :sheetId"
            + " and lower(a) = lower(:alias)")
    boolean existsAlias(String sheetId, String alias);

    /** The names of everyone on the sheets, lower-cased. */
    @Query("select lower(p.name) from Person p where p.sheetId in :sheetIds")
    List<String> namesOn(Collection<String> sheetIds);

    /** The aliases of everyone on the sheets, lower-cased. */
    @Query("select lower(a) from Person p join p.aliases a where p.sheetId in :sheetIds")
    List<String> aliasesOn(Collection<String> sheetIds);

    /** The person on the sheet with the alias, compared as names are. */
    @Query("select p from Person p join p.aliases a where p.sheetId = :sheetId and lower(a) = lower(:alias)")
    Optional<Person> findByAlias(String sheetId, String alias);

    /** The person on the sheet with the name or else the alias, compared without regard to case. */
    default Optional<Person> findByNameOrAlias(String sheetId, String name) {
        return findBySheetIdAndNameIgnoreCase(sheetId, name).or(() -> findByAlias(sheetId, name));
    }
}
-- Each person's place in the sheet's list, smallest first; people already listed keep the order
-- they were added in.
ALTER TABLE person ADD COLUMN position BIGINT;
UPDATE person SET position = id;
ALTER TABLE person ALTER COLUMN position SET NOT NULL;
CREATE INDEX person_sheet_position ON person (sheet_id, position);
-- A person's aliases: each stored with surrounding spaces removed. An alias shares the names'
-- uniqueness on the sheet (compared without regard to case), which the service keeps.
CREATE TABLE person_alias (
    person_id BIGINT       NOT NULL REFERENCES person (id),
    alias     VARCHAR(200) NOT NULL,
    PRIMARY KEY (person_id, alias)
);

